// Curated landing sites shown on the Orbital view. Coordinates always come with
// their source. A site can be shown on the map before its Horizon view data exists;
// `hasSkyData` says whether public/data/<id>/ was generated by the scripts.

export type SiteEntry = {
  id: string
  name: string
  // Planetocentric latitude (negative = south) and east longitude 0 to 360.
  latitudeDeg: number
  longitudeDeg: number
  source: string
  hasSkyData: boolean
  // Heading in the site menu.
  group: 'South pole' | 'Apollo landing sites'
}

const GLASER_2018 = 'Gläser et al. 2018, Planetary and Space Science 162, Table 1 ("this study", surface level)'
const NSSDC_APOLLO = 'NSSDC Apollo Landing Site Coordinates (Lunar Module), Wagner et al. 2017'
const GLASER_2018_2M ='Gläser et al. 2018, Planetary and Space Science 162, Table 2 (2 m above ground)'

export const SITES: SiteEntry[] = [
  {
    id: 'shackleton-rim',
    name: 'Shackleton rim',
    latitudeDeg: -89.7849,
    longitudeDeg: 203.97,
    source: GLASER_2018,
    hasSkyData: true,
    group: 'South pole',
  },
  // Connecting Ridge: Table 2 points (2 m above ground, the same height as our
  // observer), read from the PDF text on 2026-11-14. To confirm visually in the
  // PDF. Same values as scripts/sites.py.
  {
    id: 'connecting-ridge-c1',
    name: 'Connecting Ridge C1',
    latitudeDeg: -89.4398,
    longitudeDeg: 222.83,
    source: GLASER_2018_2M,
    hasSkyData: true,
    group: 'South pole',
  },
  {
    id: 'connecting-ridge-c2',
    name: 'Connecting Ridge C2',
    latitudeDeg: -89.313,
    longitudeDeg: 245.98,
    source: GLASER_2018_2M,
    hasSkyData: true,
    group: 'South pole',
  },
  // Apollo Lunar Module positions: NSSDC "Apollo Landing Site Coordinates"
  // (planetocentric, Mean Earth/Polar Axis, DE421; Wagner et al. 2017).
  // Terrain from the LOLA 118 m global DEM, 50 km radius (see scripts/build_terrain.py).
  {
    id: 'apollo-11',
    name: 'Apollo 11',
    latitudeDeg: 0.67416,
    longitudeDeg: 23.47314,
    source: NSSDC_APOLLO,
    hasSkyData: true,
    group: 'Apollo landing sites',
  },
  {
    id: 'apollo-16',
    name: 'Apollo 16',
    latitudeDeg: -8.9734,
    longitudeDeg: 15.5011,
    source: NSSDC_APOLLO,
    hasSkyData: true,
    group: 'Apollo landing sites',
  },
  {
    id: 'apollo-17',
    name: 'Apollo 17',
    latitudeDeg: 20.1911,
    longitudeDeg: 30.7723,
    source: NSSDC_APOLLO,
    hasSkyData: true,
    group: 'Apollo landing sites',
  },
]

export const DEFAULT_SITE_ID = 'shackleton-rim'

export function getSite(id: string): SiteEntry {
  const site = SITES.find((s) => s.id === id)
  if (!site) throw new Error(`Unknown site: ${id}`)
  return site
}
